const APP_VERSION='0.15.6'; const APP_DATE='19.09.2026';
const SUPABASE_URL='https://pgjhswuduxrbktjzdnty.supabase.co';
const SUPABASE_KEY='sb_publishable_MKZLIuSWTfWSs_o5ABLT0Q_hqaWlMb5';
const STATE_ID='00000000-0000-0000-0000-000000000001';
const KEY='wildverteilung_v4';
const sb=window.supabase.createClient(SUPABASE_URL,SUPABASE_KEY);
const seed={users:[],kills:[],hunts:[],groups:[],session:null};
let db=structuredClone(seed);
let authUser=null;
let syncTimer=null;
function localCandidate(){
  for(const k of [KEY,'wildverteilung_v3','wildverteilung_v2','wildverteilung_v1']){
    try{const x=JSON.parse(localStorage.getItem(k)||'null'); if(x&&Array.isArray(x.users)) return x}catch(e){}
  }
  return null;
}
function normalizeDb(x){
  x=x||structuredClone(seed); x.users=x.users||[]; x.kills=x.kills||[]; x.hunts=x.hunts||[]; x.groups=x.groups||[];
  x.users.forEach(u=>{u.groups=Array.isArray(u.groups)?u.groups:[];u.active=u.active!==false;if(!u.status)u.status=u.fixedHunter?'fixed':'guest';u.isHunter=true;u.fixedHunter=u.status==='fixed'||u.status==='tenant';u.isDistributor=u.status==='tenant';u.isAdmin=u.status==='tenant';if((u.name||'').trim().toLowerCase()==='benjamin böttcher'){u.mainAdmin=true;u.status='admin';u.isDistributor=true;u.isAdmin=true}});
  x.kills.forEach(k=>(k.parts||[]).forEach(p=>p.rejectedBy=p.rejectedBy||[])); x.hunts.forEach(h=>(h.allocations||[]).forEach(a=>a.rejectedBy=a.rejectedBy||[]));
  return x;
}
function stablePersonLocalId(uuid){
  let h=2166136261;
  for(const c of String(uuid||'')){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}
  return -(Math.abs(h>>>0)+1);
}
function personStatusFromDb(status,mainAdmin=false){return mainAdmin?'admin':status==='paechter'?'tenant':status==='fest'?'fixed':'guest'}
async function syncPersonsFromSupabase(){
  const {data:rows,error}=await sb.from('personen').select('id,vorname,nachname,status,aktiv,hauptadministrator,auth_user_id');
  if(error) throw error;
  for(const r of (rows||[])){
    const name=[r.vorname,r.nachname].filter(Boolean).join(' ').trim();
    let u=db.users.find(x=>x.sourcePersonId===r.id)
      ||(r.auth_user_id?db.users.find(x=>x.authUserId===r.auth_user_id):null)
      ||db.users.find(x=>(x.name||'').trim().toLowerCase()===name.toLowerCase());
    if(!u){u={id:stablePersonLocalId(r.id),groups:[]};db.users.push(u)}
    u.sourcePersonId=r.id;
    u.name=name||u.name||'Unbenannt';
    u.status=personStatusFromDb(r.status,!!r.hauptadministrator);
    u.active=r.aktiv!==false;
    u.mainAdmin=!!r.hauptadministrator;
    u.authUserId=r.auth_user_id||null;
    u.groups=Array.isArray(u.groups)?u.groups:[];
    u.fixedHunter=u.status==='fixed'||u.status==='tenant';
    u.isHunter=true;
    u.isDistributor=u.status==='tenant'||u.status==='admin';
    u.isAdmin=u.status==='tenant'||u.status==='admin';
  }
}
async function loadCloudState(){
  const {data,error}=await sb.from('app_state').select('daten').eq('id',STATE_ID).maybeSingle();
  if(error) throw error;
  if(data?.daten) db=normalizeDb(data.daten);
  else {
    const old=localCandidate();
    db=normalizeDb(old||seed);
  }
  // Personen/Pächter werden bei jedem Start aus der dauerhaften Supabase-Tabelle ergänzt/aktualisiert.
  // Ein App-Update kann dadurch keine bereits vorhandenen Pächter mehr verschwinden lassen.
  await syncPersonsFromSupabase();
  await saveNow();
}
async function saveNow(){
  if(!authUser)return;
  const clean=JSON.parse(JSON.stringify({...db,session:null}));
  const {error}=await sb.from('app_state').upsert({id:STATE_ID,daten:clean,geaendert_am:new Date().toISOString()});
  if(error){console.error(error);alert('Synchronisierung fehlgeschlagen: '+error.message)}
}
function save(){clearTimeout(syncTimer);syncTimer=setTimeout(saveNow,120)}
function bindSessionPerson(){
  if(!authUser)return false;
  let u=db.users.find(x=>x.authUserId===authUser.id);
  // Einmalige Zuordnung des bereits vorhandenen Hauptadministrators aus V0.14.0.
  if(!u){
    const main=db.users.find(x=>x.mainAdmin);
    if(main && !main.authUserId){main.authUserId=authUser.id;u=main;save()}
  }
  if(!u || !u.active || (u.status!=='tenant'&&u.status!=='admin')){
    db.session=null;
    return false;
  }
  db.session=u.id;
  return true;
}
const A=document.querySelector('#app');
function confirmSaved(msg='Gespeichert'){alert('✓ '+msg);}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function shell(x){A.innerHTML=`<div class='wrap'>${x}</div>`} function user(){return db.users.find(x=>x.id===db.session)} function hunters(){return db.users.filter(x=>x.active&&!x.deleted)} function fixedHunters(){return db.users.filter(x=>x.active&&!x.deleted&&!x.temporary&&(x.status==='fixed'||x.status==='tenant'||x.fixedHunter))} function canDistribute(){let u=user();return !!(u&&(u.isDistributor||u.isAdmin))} function isAdmin(){return !!user()?.isAdmin}
function login(){shell(`<div class='brand'><div class='mark'>🦌</div><h1>Wildverteilung</h1><div class='small'>Jagdgemeinschaft</div></div><div class='card'><label>E-Mail</label><input id='l' type='email' autocomplete='username' placeholder='E-Mail des Pächter-Zugangs'><label>Passwort</label><input id='p' type='password' autocomplete='current-password'><button class='btn' id='go'>Anmelden</button><div class='small' style='margin-top:12px'>Nur Pächter haben Zugang. Anmeldung läuft zentral über Supabase Auth.</div></div><p class='small' style='text-align:center'><b>Version ${APP_VERSION}</b> · Stand ${APP_DATE}</p>`);go.onclick=async()=>{go.disabled=true;go.textContent='Anmeldung …';const {data,error}=await sb.auth.signInWithPassword({email:l.value.trim(),password:p.value});if(error){go.disabled=false;go.textContent='Anmelden';return alert('Anmeldung fehlgeschlagen: '+error.message)}authUser=data.user;try{await loadCloudState();if(!bindSessionPerson()){await sb.auth.signOut();authUser=null;alert('Dieser Zugang ist keinem aktiven Pächter zugeordnet.');return login()}home()}catch(e){await sb.auth.signOut();authUser=null;alert('Datenbank konnte nicht geladen werden. Bitte zuerst die SQL-Datei V0.14 ausführen.\n\n'+e.message);login()}}}
